// Generated by scripts/build-print-station.mjs — do not edit by hand.
//
// The Print Station's own source, compiled in so the partner download route
// can zip it. A serverless function does not carry public/ on its disk, so
// reading the files at request time would work locally and 500 in production.
//
// print-station/distribution.test.mjs fails if this drifts from the source.

export const PRINT_STATION_FILES: Record<string, string> = {
  "station.mjs": "#!/usr/bin/env node\nimport { createServer } from \"node:http\";\nimport { execFile } from \"node:child_process\";\nimport { mkdtempSync, writeFileSync, rmSync } from \"node:fs\";\nimport { tmpdir } from \"node:os\";\nimport { join } from \"node:path\";\n\nimport { adoptedBundledKey, configPath, configProblems, isReady, loadConfig, saveConfig } from \"./lib/config.mjs\";\nimport { createApi } from \"./lib/api.mjs\";\nimport { createLog } from \"./lib/log.mjs\";\nimport { createWorker, diagnose } from \"./lib/worker.mjs\";\nimport { ensurePrintHelper, listPrinters, printFile } from \"./lib/printer.mjs\";\nimport { renderPage } from \"./lib/page.mjs\";\nimport { PRINT_STATION_VERSION } from \"./lib/version.mjs\";\n\n/**\n * DigiConnect Print Station.\n *\n * A shop owner double-clicks this, a page opens on their own computer, they\n * paste the key from their dashboard and pick a printer. From then on the\n * computer prints what customers order at the QR taped to the counter, and\n * deletes their files the moment the pages are out.\n *\n * It listens on localhost only. Nothing on the shop's network — let alone the\n * internet — can reach this program: it makes outbound calls to the website\n * and answers nobody.\n */\n\nconst PORT = Number(process.env.DCPS_PORT || 7171);\n\nconst log = createLog();\nconst state = {\n  running: false,\n  connected: false,\n  queued: 0,\n  printed: 0,\n  failed: 0,\n  lastError: null,\n  lastPollAt: null,\n  stoppedReason: null,\n  stationName: null,\n};\n\nlet config = loadConfig();\nlet printers = [];\nlet worker = null;\n\n/* ─────────────────────────────────────────────────────────────────────────\n   The loop\n   ───────────────────────────────────────────────────────────────────────── */\n\nfunction stopWorker() {\n  worker?.stop();\n  worker = null;\n  state.running = false;\n  state.connected = false;\n}\n\nfunction startWorker() {\n  stopWorker();\n\n  const problems = configProblems(config);\n  if (problems.length) {\n    state.stoppedReason = problems[0];\n    return;\n  }\n\n  state.stoppedReason = null;\n  const api = createApi({ serverUrl: config.serverUrl, agentToken: config.agentToken });\n\n  worker = createWorker({\n    api,\n    config,\n    printers,\n    state,\n    log: log.push,\n    print: ({ filePath, job }) =>\n      printFile({ filePath, printerName: config.printerName, job, config }),\n  });\n\n  worker.start();\n  state.running = true;\n  log.push(\"info\", `Watching for jobs. Printing to \"${config.printerName}\".`);\n}\n\n/* ─────────────────────────────────────────────────────────────────────────\n   The test page\n   ───────────────────────────────────────────────────────────────────────── */\n\n/**\n * A one-page PDF, built by hand.\n *\n * Written as bytes rather than pulled from a library because this program has\n * no dependencies on purpose — a shop owner should be able to run it on a\n * counter PC with nothing installed but Node. It exists so a partner can\n * prove the printer works before a customer is standing there.\n */\nfunction testPagePdf() {\n  const text = `DigiConnect Print Station works. ${new Date().toLocaleString()}`;\n  const content = `BT /F1 16 Tf 60 700 Td (${text.replace(/[()\\\\]/g, \"\")}) Tj ET`;\n  const objects = [\n    \"<< /Type /Catalog /Pages 2 0 R >>\",\n    \"<< /Type /Pages /Kids [3 0 R] /Count 1 >>\",\n    \"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>\",\n    `<< /Length ${content.length} >>\\nstream\\n${content}\\nendstream`,\n    \"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>\",\n  ];\n\n  let pdf = \"%PDF-1.4\\n\";\n  const offsets = [];\n  objects.forEach((object, index) => {\n    offsets.push(pdf.length);\n    pdf += `${index + 1} 0 obj\\n${object}\\nendobj\\n`;\n  });\n\n  const xref = pdf.length;\n  pdf += `xref\\n0 ${objects.length + 1}\\n0000000000 65535 f \\n`;\n  for (const offset of offsets) pdf += `${String(offset).padStart(10, \"0\")} 00000 n \\n`;\n  pdf += `trailer\\n<< /Size ${objects.length + 1} /Root 1 0 R >>\\nstartxref\\n${xref}\\n%%EOF\\n`;\n\n  return Buffer.from(pdf, \"latin1\");\n}\n\nasync function printTestPage() {\n  if (!config.printerName) throw new Error(\"Choose a printer first.\");\n\n  const folder = mkdtempSync(join(tmpdir(), \"dcps-test-\"));\n  const path = join(folder, \"test.pdf\");\n  writeFileSync(path, testPagePdf());\n  try {\n    await printFile({\n      filePath: path,\n      printerName: config.printerName,\n      job: { copies: 1, pages: 1, paper_size: \"A4\", color_mode: \"mono\" },\n      config,\n    });\n  } finally {\n    rmSync(folder, { recursive: true, force: true });\n  }\n}\n\n/* ─────────────────────────────────────────────────────────────────────────\n   The local screen\n   ───────────────────────────────────────────────────────────────────────── */\n\nfunction json(response, status, body) {\n  const payload = JSON.stringify(body);\n  response.writeHead(status, {\n    \"Content-Type\": \"application/json\",\n    \"Content-Length\": Buffer.byteLength(payload),\n    \"Cache-Control\": \"no-store\",\n  });\n  response.end(payload);\n}\n\nasync function readBody(request) {\n  const chunks = [];\n  for await (const chunk of request) {\n    chunks.push(chunk);\n    // A setup form is a few hundred bytes. Anything larger is not a form.\n    if (chunks.reduce((total, part) => total + part.length, 0) > 64 * 1024) break;\n  }\n  try {\n    return JSON.parse(Buffer.concat(chunks).toString(\"utf8\") || \"{}\");\n  } catch {\n    return {};\n  }\n}\n\nconst server = createServer(async (request, response) => {\n  const url = new URL(request.url, \"http://localhost\");\n\n  if (url.pathname === \"/\" && request.method === \"GET\") {\n    const page = renderPage();\n    response.writeHead(200, { \"Content-Type\": \"text/html; charset=utf-8\", \"Cache-Control\": \"no-store\" });\n    response.end(page);\n    return;\n  }\n\n  if (url.pathname === \"/api/state\" && request.method === \"GET\") {\n    json(response, 200, {\n      ...state,\n      config,\n      printers,\n      version: PRINT_STATION_VERSION,\n      problems: configProblems(config),\n      configPath: configPath(),\n      log: log.lines(),\n    });\n    return;\n  }\n\n  if (url.pathname === \"/api/save\" && request.method === \"POST\") {\n    const body = await readBody(request);\n    // The token field is left untouched when the form sends back nothing —\n    // a partner editing the poll interval should not have to fetch their key\n    // out of a drawer.\n    config = saveConfig({ ...config, ...body, agentToken: String(body.agentToken ?? config.agentToken) });\n    printers = await listPrinters();\n    log.push(\"info\", \"Settings saved.\");\n    startWorker();\n    json(response, 200, { ok: isReady(config), problems: configProblems(config) });\n    return;\n  }\n\n  if (url.pathname === \"/api/check\" && request.method === \"POST\") {\n    /*\n      The button that ends the guessing.\n\n      It asks the website who this key belongs to and reports the answer in\n      words, rather than leaving the shop to infer it from a status code that\n      means four different things.\n    */\n    const api = createApi({ serverUrl: config.serverUrl, agentToken: config.agentToken });\n    const findings = await diagnose({ api, config, printers });\n    for (const finding of findings) {\n      if (finding.level === \"error\") log.push(\"error\", finding.text);\n      else if (finding.level === \"fix\") log.push(\"warn\", finding.text);\n    }\n    json(response, 200, { findings });\n    return;\n  }\n\n  if (url.pathname === \"/api/test-print\" && request.method === \"POST\") {\n    try {\n      await printTestPage();\n      log.push(\"success\", `Test page sent to \"${config.printerName}\".`);\n      json(response, 200, { ok: true, printer: config.printerName });\n    } catch (error) {\n      const message = error instanceof Error ? error.message : String(error);\n      log.push(\"error\", `Test page failed: ${message}`);\n      json(response, 200, { ok: false, error: message });\n    }\n    return;\n  }\n\n  json(response, 404, { error: \"Not found\" });\n});\n\n/** Open the shop owner's browser at the setup page, on whichever OS this is. */\nfunction openBrowser(url) {\n  const command =\n    process.platform === \"win32\" ? [\"cmd\", [\"/c\", \"start\", \"\", url]]\n    : process.platform === \"darwin\" ? [\"open\", [url]]\n    : [\"xdg-open\", [url]];\n  execFile(command[0], command[1], { windowsHide: true }, () => {\n    /* No browser is not a failure — the address is printed below. */\n  });\n}\n\n/*\n  Bound to 127.0.0.1 rather than every interface.\n\n  This program holds the key to a shop's print queue and, briefly, its\n  customers' documents. On a shop's flat network — often shared with a\n  neighbour's wifi — a server listening on 0.0.0.0 would let anybody on it\n  read the settings page and change the printer.\n*/\nserver.listen(PORT, \"127.0.0.1\", async () => {\n  console.log(\"\");\n  console.log(`  DigiConnect Print Station  v${PRINT_STATION_VERSION}`);\n  console.log(`  Settings: http://localhost:${PORT}`);\n  console.log(`  Config file: ${configPath()}`);\n  console.log(\"\");\n\n  // First line in the log, so a screenshot always says which build this is.\n  log.push(\"info\", `DigiConnect Print Station v${PRINT_STATION_VERSION}`);\n\n  if (adoptedBundledKey(config)) {\n    log.push(\"info\", \"Key taken from this downloaded folder.\");\n  }\n\n  printers = await listPrinters();\n  if (!printers.length) log.push(\"warn\", \"No printer found on this computer yet.\");\n\n  // Best effort, and never blocking: photos print without it either way.\n  await ensurePrintHelper({ serverUrl: config.serverUrl, config, log: log.push });\n\n  startWorker();\n  if (!isReady(config)) openBrowser(`http://localhost:${PORT}`);\n});\n\nserver.on(\"error\", (error) => {\n  if (error.code === \"EADDRINUSE\") {\n    console.error(`\\n  Print Station is already running. Open http://localhost:${PORT}\\n`);\n    openBrowser(`http://localhost:${PORT}`);\n    process.exit(0);\n  }\n  console.error(error);\n  process.exit(1);\n});\n\nfor (const signal of [\"SIGINT\", \"SIGTERM\"]) {\n  process.on(signal, () => {\n    stopWorker();\n    server.close(() => process.exit(0));\n  });\n}\n",
  "README.md": "# DigiConnect Print Station\n\nThe program that actually prints.\n\nA customer scans the QR taped to your counter, chooses A4 or A3, black or\ncolour, uploads their file and pays. This program — running on the computer\nyour printer is plugged into — collects that job, prints it, and deletes the\nfile. Nobody in the shop opens the customer's document, and nothing of theirs\nis left on the computer afterwards.\n\n---\n\n## Install it (Windows)\n\n**The easy way.** In your partner dashboard, open **Print counter** and press\n**Print Station download kijiye**. You get a zip with your key already inside —\nnothing to paste.\n\n1. Unzip the folder somewhere you will find it again. Do not run it from\n   inside the zip.\n2. Double-click **Start Print Station**.\n3. If it asks for Node.js, install the **LTS** build from\n   [nodejs.org](https://nodejs.org/en/download) and double-click again.\n\nEvery download issues a new key and retires the old one, so keep one folder on\none computer.\n\n**The other way**, if the download is blocked. Open **PowerShell** and paste:\n\n```powershell\nirm https://www.rnos.in/print-station/install.ps1 | iex\n```\n\nThen copy your key from the dashboard into the settings page yourself. If\nPowerShell refuses to run it, run `Set-ExecutionPolicy -Scope Process -Bypass`\nfirst.\n\n### Printing helper\n\nThe program fetches a small helper on first run, by itself. You do not install\nanything. If it cannot be fetched, printing falls back to Windows' own PDF\nviewer — still correct on copies, paper size and colour, just slower, one copy\nat a time.\n\n## Install it (macOS or Linux)\n\nDownload the folder, then:\n\n```sh\n./start-print-station.sh\n```\n\nPrinting goes through CUPS (`lp`), which is already there. Nothing else to\ninstall.\n\n---\n\n## Set it up\n\nThe program opens a page on your own computer at **http://localhost:7171**.\n\n1. **Your key** — copy it from your partner dashboard under **Print counter**.\n   It starts with `dcp_` and is shown only once. If you have lost it, issue a\n   new one from the same screen; the old one stops working immediately.\n2. **Printer** — pick the printer from the list. The list is what Windows or\n   macOS itself reports, so if the printer is missing here it is missing from\n   the computer too.\n3. **Print a test page** — do this before your first customer. A page comes\n   out of the tray, and you know the whole chain works.\n\nIf you used the download, steps 1 and 2 are already done for you.\n\n---\n\n## Run it without the black window\n\nThe console window is not the program's home, only its front door. Nobody at a\ncounter should have to guard it, and one accidental X at closing time means the\nnext customer pays for pages that never come out.\n\nDouble-click **Background me chalaiye** once. From then on:\n\n- The program runs with no window at all.\n- It starts by itself every time the computer is switched on.\n- Its state is at **http://localhost:7171**, same as before.\n\nTo go back to the old way, double-click **Background band kijiye** — that stops\nthe hidden copy and removes it from Windows startup.\n\nIt needs no administrator rights: it writes one shortcut into your own Startup\nfolder (`shell:startup`), which is why it works on a shop machine whose owner\nis not an admin. The hidden start uses `wscript`; on a Windows with VBScript\nremoved it falls back to PowerShell.\n\nOne thing it does not do: restart itself if the program crashes. It comes back\non the next reboot. If you see printing stop with the computer still on, open\nhttp://localhost:7171 — if that page does not load, run **Background me\nchalaiye** again.\n\n---\n\n## What the screen tells you\n\n| It says | It means |\n| --- | --- |\n| **Connected** | Talking to the website. Jobs will print. |\n| **Trying to reach the website…** | Your internet is down. Jobs are safe and will print when it returns. |\n| **Stopped** | Something needs you — the message underneath says what. |\n| **Waiting** | Jobs paid for and not yet printed. |\n\n---\n\n## When something goes wrong\n\n**\"Your key was refused.\"**\nThe key is wrong or has been replaced — most often because a newer download\nretired it. Download the bundle again, or issue a new key from the dashboard.\n\n**\"The server cannot reach its database right now.\"**\nNot your key, and nothing to re-paste. The site is having trouble; the program\nkeeps retrying and will pick up where it left off.\n\n**\"No internet.\"**\nNothing is lost. The jobs stay on the server and print the moment the\nconnection is back.\n\n**\"The printer did not accept the job.\"**\nPaper, power, or an error light on the printer itself. Fix it, then use\n**Print a test page** to confirm before the next customer.\n\n**Nothing prints and the screen says Connected.**\nThe job is queueing against a different counter. Check the key belongs to this\nshop — the shop's name appears next to the Connected light once it has spoken\nto the website.\n\n---\n\n## What this program does with a customer's file\n\n- Downloads it to a temporary folder only when it is about to print.\n- Deletes it as soon as the print command returns — including when printing\n  failed.\n- Never writes a customer's file name or contents to a log file.\n- Listens on `127.0.0.1` only, so nothing else on the shop's network — or the\n  internet — can reach it.\n- Stores your key in your own user profile, readable only by you.\n\nThe counter is at\n`%LOCALAPPDATA%\\DigiConnectPrintStation\\config.json` on Windows and\n`~/.config/digiconnect-print-station/config.json` elsewhere. Deleting it\nresets the setup.\n\n---\n\n## For developers\n\nSource of truth is `print-station/` in the repository. `public/print-station/`\nis a copy for downloading, rebuilt with:\n\n```sh\nnode scripts/build-print-station.mjs\n```\n\n`print-station/distribution.test.mjs` fails if the two drift apart. The rest\nof the tests run with the main suite (`npm test`).\n",
  "Start Print Station.bat": "@echo off\ntitle DigiConnect Print Station\ncd /d \"%~dp0\"\n\nREM  The shop owner double-clicks this file. Nothing else.\nREM\nREM  Node is the only thing this program needs, and a counter PC usually does\nREM  not have it. Rather than failing with \"node is not recognised\", which\nREM  tells a shop owner nothing -- this checks first and sends them to the one\nREM  page that fixes it.\n\nREM  Ye file akeli kaam nahi karti.\nREM\nREM  A shop opened the zip in Explorer, dragged this one file onto the\nREM  Desktop, and ran it. Node then looked for station.mjs next to it, found\nREM  nothing, and printed a module-not-found stack trace with a path in it --\nREM  which reads like the program is broken rather than in the wrong place.\nREM  It printed fine the day before, from inside the extracted folder.\n\nif not exist \"%~dp0station.mjs\" goto :nofolder\n\nwhere node >nul 2>nul\nif errorlevel 1 (\n  echo.\n  echo   DigiConnect Print Station needs Node.js, which is not installed yet.\n  echo.\n  echo   Opening the download page. Install it, then run this file again.\n  echo   Choose the \"LTS\" button and click Next until it finishes.\n  echo.\n  start \"\" \"https://nodejs.org/en/download\"\n  pause\n  exit /b 1\n)\n\necho.\necho   Starting DigiConnect Print Station...\necho   Leave this window open. Closing it stops printing.\necho.\n\nnode \"%~dp0station.mjs\"\n\nREM  If the program stops, the window stays so the reason can be read.\necho.\necho   Print Station has stopped.\npause\nexit /b 0\n\n:nofolder\necho.\necho   Ye file akele nahi chalti.\necho.\necho   Lagta hai \"Start Print Station\" ko zip se nikal kar alag rakh diya gaya\necho   hai. Iske saath station.mjs aur lib folder bhi hone chahiye.\necho.\necho   Kya kariye:\necho     1. Downloads me DigiConnect-Print-Station...zip par right-click\necho     2. \"Extract All\" -^> Extract\necho     3. Jo folder bane, uske ANDAR jaiye\necho     4. Wahin se \"Start Print Station\" par double-click\necho.\necho   Abhi ye yahan se chalane ki koshish hui:\necho   %~dp0\necho.\npause\nexit /b 1\n",
  "Background me chalaiye.bat": "@echo off\ntitle DigiConnect Print Station - background me chalaiye\ncd /d \"%~dp0\"\n\nREM  Double-click this once, and the black window is never needed again.\nREM\nREM  The program keeps running with no window, and starts by itself every\nREM  time the computer is switched on. Undo it with \"Background band kijiye\".\n\nif not exist \"%~dp0station.mjs\" goto :nofolder\n\npowershell -NoProfile -ExecutionPolicy Bypass -File \"%~dp0lib\\background.ps1\"\npause\nexit /b 0\n\n:nofolder\necho.\necho   Ye file akele nahi chalti.\necho.\necho   Poori zip ko \"Extract All\" kijiye, aur jo folder bane uske ANDAR se\necho   ye file chalaiye - station.mjs aur lib isi ke saath hone chahiye.\necho.\necho   Abhi ye yahan se chalane ki koshish hui:\necho   %~dp0\necho.\npause\nexit /b 1\n",
  "Background band kijiye.bat": "@echo off\ntitle DigiConnect Print Station - background band kijiye\ncd /d \"%~dp0\"\n\nREM  Stops the hidden copy and takes it out of Windows startup. Printing then\nREM  happens only while \"Start Print Station\" is open, as it did before.\n\nif not exist \"%~dp0station.mjs\" goto :nofolder\n\npowershell -NoProfile -ExecutionPolicy Bypass -File \"%~dp0lib\\background.ps1\" -Remove\npause\nexit /b 0\n\n:nofolder\necho.\necho   Ye file akele nahi chalti. Poori zip Extract kijiye aur folder ke\necho   ANDAR se chalaiye.\necho.\npause\nexit /b 1\n",
  "start-print-station.sh": "#!/bin/sh\n# The same thing for a shop running macOS or Linux.\ncd \"$(dirname \"$0\")\" || exit 1\n\n# Same trap as on Windows: this file copied out of the folder on its own,\n# with station.mjs left behind.\nif [ ! -f ./station.mjs ]; then\n  echo \"\"\n  echo \"  This file cannot run on its own.\"\n  echo \"  Extract the whole zip and run it from inside that folder,\"\n  echo \"  next to station.mjs and lib/.\"\n  echo \"\"\n  exit 1\nfi\n\nif ! command -v node >/dev/null 2>&1; then\n  echo \"\"\n  echo \"  DigiConnect Print Station needs Node.js.\"\n  echo \"  Install it from https://nodejs.org/en/download and run this again.\"\n  echo \"\"\n  exit 1\nfi\n\nexec node ./station.mjs\n",
  "lib/config.mjs": "import { mkdirSync, readFileSync, writeFileSync, existsSync } from \"node:fs\";\nimport { homedir, platform } from \"node:os\";\nimport { dirname, join } from \"node:path\";\nimport { fileURLToPath } from \"node:url\";\n\n/**\n * What this computer remembers between restarts.\n *\n * A shop owner sets this up once. The file lives in the operating system's\n * own per-user config location rather than beside the program, so that\n * replacing the program folder — a re-download, an update — does not lose the\n * key and force a trip back to the website.\n */\n\nexport const DEFAULTS = {\n  /*\n    Where the counter lives.\n\n    The www is not decoration. The bare domain answers with a redirect to\n    this one, and a redirect across origins costs the Authorization header —\n    so every key sent to the bare domain arrived with no key at all, and the\n    server truthfully said it was refused. Overridable, so a test install can\n    point elsewhere.\n  */\n  serverUrl: \"https://www.rnos.in\",\n  /** The key issued at /ap/print. Shown once, so it is stored here. */\n  agentToken: \"\",\n  /** The printer's name as the operating system spells it. */\n  printerName: \"\",\n  /**\n   * How often to ask for work.\n   *\n   * Five seconds: a customer is standing at the counter watching, so a minute\n   * feels broken, and anything under a second is a shop hammering a server\n   * all day for nothing.\n   */\n  pollSeconds: 5,\n  /** Print in colour only when the job asked for it. */\n  duplex: false,\n  /** Path to SumatraPDF, if the shop uses it. Found automatically when blank. */\n  sumatraPath: \"\",\n  /*\n    The download key this computer has already taken.\n\n    Not a setting anybody edits — it is how the program tells \"the folder I\n    was started from carries a newer key\" from \"the shop typed its own key\n    in\". Without it a bundle's key would either be ignored forever, or\n    clobber a hand-entered one on every restart.\n  */\n  seededFrom: \"\",\n};\n\nexport function configDir() {\n  const home = homedir();\n  if (platform() === \"win32\") {\n    return join(process.env.APPDATA || join(home, \"AppData\", \"Roaming\"), \"DigiConnectPrintStation\");\n  }\n  if (platform() === \"darwin\") {\n    return join(home, \"Library\", \"Application Support\", \"DigiConnectPrintStation\");\n  }\n  return join(process.env.XDG_CONFIG_HOME || join(home, \".config\"), \"digiconnect-print-station\");\n}\n\nexport function configPath() {\n  return join(configDir(), \"config.json\");\n}\n\n/**\n * Clean whatever was on disk, or in a form post, into a usable config.\n *\n * Written as a pure function so the rules can be tested without a filesystem:\n * every value a shop owner can type passes through here, and a mistyped poll\n * interval must never turn into an infinite loop.\n */\nexport function normalizeConfig(raw) {\n  const input = raw && typeof raw === \"object\" ? raw : {};\n\n  const serverUrl = String(input.serverUrl ?? DEFAULTS.serverUrl).trim().replace(/\\/+$/, \"\");\n\n  /*\n    \"Not provided\" is checked before Number, not after.\n\n    `Number(null)` and `Number(\"\")` are both 0, which is perfectly finite —\n    so a config file missing this field, or a form that left it blank, would\n    clamp to the two-second floor and quietly triple this shop's traffic to\n    the server forever.\n  */\n  const pollGiven = input.pollSeconds !== null && input.pollSeconds !== undefined && input.pollSeconds !== \"\";\n  const pollRaw = pollGiven ? Number(input.pollSeconds) : NaN;\n\n  return {\n    serverUrl: serverUrl || DEFAULTS.serverUrl,\n    agentToken: String(input.agentToken ?? \"\").trim(),\n    printerName: String(input.printerName ?? \"\").trim(),\n    // Clamped, not rejected: a shop owner who types 0 means \"as fast as\n    // possible\", and a shop owner who types 3600 has made a typo they should\n    // not have to diagnose from a stalled queue.\n    pollSeconds: Number.isFinite(pollRaw) ? Math.min(60, Math.max(2, Math.round(pollRaw))) : DEFAULTS.pollSeconds,\n    duplex: Boolean(input.duplex),\n    sumatraPath: String(input.sumatraPath ?? \"\").trim(),\n    seededFrom: String(input.seededFrom ?? \"\").trim(),\n  };\n}\n\n/** Everything that must be true before the loop is allowed to start. */\nexport function configProblems(config) {\n  const problems = [];\n  if (!config.agentToken) problems.push(\"Paste the key from your DigiConnect partner dashboard.\");\n  else if (!config.agentToken.startsWith(\"dcp_\")) problems.push(\"That key does not look right — it should start with dcp_.\");\n  if (!config.printerName) problems.push(\"Choose the printer that should print the jobs.\");\n  if (!/^https?:\\/\\//i.test(config.serverUrl)) problems.push(\"The server address must start with http:// or https://.\");\n  return problems;\n}\n\nexport function isReady(config) {\n  return configProblems(config).length === 0;\n}\n\n/**\n * The settings that came inside the download, if any.\n *\n * A partner who downloads from their own dashboard gets a bundle with their\n * key and their site address already in it, so there is nothing to paste and\n * nothing to mistype.\n */\nfunction bundledConfig() {\n  try {\n    const beside = join(dirname(fileURLToPath(import.meta.url)), \"..\", \"config.json\");\n    if (!existsSync(beside)) return null;\n    return JSON.parse(readFileSync(beside, \"utf8\"));\n  } catch {\n    return null;\n  }\n}\n\nfunction readStored() {\n  const path = configPath();\n  if (!existsSync(path)) return null;\n  try {\n    const parsed = JSON.parse(readFileSync(path, \"utf8\"));\n    return parsed && typeof parsed === \"object\" ? parsed : null;\n  } catch {\n    // A corrupt file must not stop the shop from opening.\n    return null;\n  }\n}\n\n/**\n * The settings this computer runs on.\n *\n * The awkward case, and the one that actually bit a shop: a partner who had\n * already set the program up by hand downloaded a fresh bundle. Downloading\n * issues a new key and retires the old one — so the saved settings now held a\n * key certain to be refused, while the working key sat unread in the folder\n * they had just double-clicked. \"Your key was refused\", on the very action\n * meant to make keys somebody else's problem.\n *\n * So a bundle's key beats a saved one — but only once per bundle, and only\n * the key. Which printer this shop picked on this computer is not something a\n * download knows, and not something it should overwrite.\n */\nexport function loadConfig() {\n  const stored = readStored();\n  const bundled = bundledConfig();\n  const bundledToken = String(bundled?.agentToken ?? \"\").trim();\n\n  if (!stored) {\n    // Written out now, so the first save from the settings page edits a real\n    // file rather than re-seeding from the folder on every restart.\n    return bundled ? saveConfig({ ...bundled, seededFrom: bundledToken }) : normalizeConfig({});\n  }\n\n  if (bundledToken && bundledToken !== String(stored.seededFrom ?? \"\").trim()) {\n    return saveConfig({\n      ...stored,\n      agentToken: bundledToken,\n      serverUrl: bundled.serverUrl || stored.serverUrl,\n      seededFrom: bundledToken,\n    });\n  }\n\n  return normalizeConfig(stored);\n}\n\n/** Did this start take its key from the folder it was run out of? */\nexport function adoptedBundledKey(config, bundled = bundledConfig()) {\n  const token = String(bundled?.agentToken ?? \"\").trim();\n  return Boolean(token) && token === config.agentToken && token === config.seededFrom;\n}\n\n\nexport function saveConfig(config) {\n  const clean = normalizeConfig(config);\n  const path = configPath();\n  mkdirSync(dirname(path), { recursive: true });\n  writeFileSync(path, JSON.stringify(clean, null, 2), { mode: 0o600 });\n  return clean;\n}\n\n/** The config as it is safe to show on a screen or paste into a support chat. */\nexport function redactConfig(config) {\n  const token = config.agentToken;\n  return {\n    ...config,\n    agentToken: token ? `${token.slice(0, 8)}…${token.slice(-4)}` : \"\",\n  };\n}\n",
  "lib/api.mjs": "/**\n * Everything this program says to the server.\n *\n * Four calls, and nothing else. Written against the endpoints in\n * src/app/api/print/agent/ — if one of those changes shape, this file is the\n * only place that has to follow.\n */\n\nexport class ApiError extends Error {\n  constructor(message, status) {\n    super(message);\n    this.name = \"ApiError\";\n    this.status = status;\n  }\n}\n\n/**\n * Whether a failure is worth trying again.\n *\n * A wrong key will be just as wrong in five seconds, and retrying it forever\n * fills a log with noise that hides the real problem. A timeout or a 502 is a\n * shop's broadband, and giving up on those would mean walking to the computer\n * every time the wifi blinked.\n */\nexport function isRetryable(status) {\n  if (status === undefined || status === null) return true; // network-level: no reply at all\n  if (status === 408 || status === 425 || status === 429) return true;\n  return status >= 500;\n}\n\n/** Back off after repeated failures, but never so far that a shop stalls. */\nexport function backoffSeconds(consecutiveFailures, base = 5) {\n  const capped = Math.min(6, Math.max(0, consecutiveFailures));\n  return Math.min(120, base * 2 ** capped);\n}\n\n\n/**\n * Is this redirect still the same website?\n *\n * rnos.in answers a request for the bare domain with a 307 to www.rnos.in.\n * Those are different origins, so `fetch` obeys the spec and strips the\n * Authorization header before following — the server then sees no key at all\n * and says the key was refused. Every key a shop tried was refused for this\n * reason, correct ones included, and nothing on either side could tell.\n *\n * So the redirect is followed by hand, with the header re-attached — but only\n * when it stays on the same site. A credential must never be replayed to\n * wherever a redirect happens to point.\n */\nexport function sameSite(fromUrl, toUrl) {\n  try {\n    const bare = (url) => new URL(url).hostname.toLowerCase().replace(/^www\\./, \"\");\n    return bare(fromUrl) === bare(toUrl);\n  } catch {\n    return false;\n  }\n}\n\n/** Where a redirect actually points, resolving a relative Location. */\nexport function redirectTarget(currentUrl, location) {\n  if (!location) return null;\n  try {\n    return new URL(location, currentUrl).toString();\n  } catch {\n    return null;\n  }\n}\n\nexport function createApi({ serverUrl, agentToken, fetchImpl = fetch, timeoutMs = 30_000 }) {\n  const base = String(serverUrl).replace(/\\/+$/, \"\");\n\n  async function call(path, { method = \"GET\", body } = {}) {\n    const controller = new AbortController();\n    const timer = setTimeout(() => controller.abort(), timeoutMs);\n\n    try {\n      const send = (url) =>\n        fetchImpl(url, {\n          method,\n          headers: {\n            Authorization: `Bearer ${agentToken}`,\n            ...(body ? { \"Content-Type\": \"application/json\" } : {}),\n          },\n          body: body ? JSON.stringify(body) : undefined,\n          signal: controller.signal,\n          // Handled below rather than by fetch, so the credential survives.\n          redirect: \"manual\",\n        });\n\n      let url = `${base}${path}`;\n      let response = await send(url);\n\n      /*\n        Follow at most a couple of hops, and only within the same site.\n\n        Two is enough for the real case (bare domain to www, or http to\n        https) and a low enough ceiling that a redirect loop cannot spin\n        here. A hop that leaves the site is not followed with the key\n        attached — that would hand a shop's credential to whoever the\n        Location pointed at.\n      */\n      for (let hop = 0; hop < 2 && response.status >= 300 && response.status < 400; hop += 1) {\n        const next = redirectTarget(url, response.headers?.get?.(\"location\"));\n        if (!next || !sameSite(url, next)) break;\n        url = next;\n        response = await send(url);\n      }\n\n      const text = await response.text();\n      let json = null;\n      try {\n        json = text ? JSON.parse(text) : null;\n      } catch {\n        json = null;\n      }\n\n      if (!response.ok) {\n        throw new ApiError(json?.error || `Server replied ${response.status}`, response.status);\n      }\n      return json ?? {};\n    } finally {\n      clearTimeout(timer);\n    }\n  }\n\n  return {\n    /** Jobs waiting at this station. Also the heartbeat the dashboard reads. */\n    listJobs: (printers = []) => {\n      const query = printers.length ? `?printers=${encodeURIComponent(printers.join(\",\"))}` : \"\";\n      return call(`/api/print/agent/jobs${query}`);\n    },\n\n    /** Take a job, and get a download link that expires in five minutes. */\n    claim: (jobId) => call(\"/api/print/agent/claim-job\", { method: \"POST\", body: { job_id: jobId } }),\n\n    /** \"Is this key any good, and whose counter is it?\" */\n    whoami: () => call(\"/api/print/agent/whoami\"),\n\n    /** Say what happened. The customer's screen is watching this. */\n    report: (jobId, status, errorMessage) =>\n      call(\"/api/print/agent/update-status\", {\n        method: \"POST\",\n        body: { job_id: jobId, status, error_message: errorMessage ?? \"\" },\n      }),\n  };\n}\n",
  "lib/worker.mjs": "import { mkdtempSync, rmSync, writeFileSync } from \"node:fs\";\nimport { tmpdir } from \"node:os\";\nimport { join } from \"node:path\";\n\nimport { backoffSeconds, isRetryable } from \"./api.mjs\";\n\n/**\n * The loop: ask for work, take it, print it, say what happened.\n *\n * Deliberately dull. The interesting decisions — which job to take next, when\n * to back off, whether a failure is the shop's or the server's — are pure\n * functions above the loop so they can be tested without a printer, a network\n * or a clock.\n */\n\n/**\n * Which job to print next.\n *\n * Oldest first, because the customer who has been waiting longest is the one\n * about to ask. Jobs another agent already holds a live claim on are skipped:\n * the server would refuse the claim anyway, and trying wastes the interval a\n * waiting customer is counting.\n */\nexport function nextJob(jobs, now = Date.now()) {\n  const available = (Array.isArray(jobs) ? jobs : []).filter((job) => {\n    if (!job || !job.id) return false;\n    if (!job.claimed_by_agent) return true;\n    const expiry = job.claim_expires_at ? Date.parse(job.claim_expires_at) : NaN;\n    return Number.isFinite(expiry) && expiry < now;\n  });\n\n  available.sort((a, b) => Date.parse(a.created_at ?? 0) - Date.parse(b.created_at ?? 0));\n  return available[0] ?? null;\n}\n\n/**\n * What to tell the shop owner when something breaks.\n *\n * A shop owner is not going to read a stack trace, and \"Error: ECONNREFUSED\"\n * on a screen behind a counter is the same as no message at all. Each of\n * these names the thing they can actually go and fix.\n */\nexport function describeFailure(error) {\n  const status = error?.status;\n  const raw = String(error?.message ?? error ?? \"Something went wrong\");\n\n  if (status === 401) {\n    /*\n      Almost always the same story: a newer download was made, which issues a\n      new key and retires this one, and the older folder is still the one\n      being run. Naming that is far more use than \"issue a new one\", which is\n      what this used to say and what sent a shop round the loop again.\n    */\n    return \"Your key was refused. A newer download replaced it — run the newest downloaded folder, or download again from your dashboard.\";\n  }\n  if (status === 409) return \"Another computer took that job first. Nothing to do.\";\n  if (status === 404) return \"That job is no longer on the server.\";\n  if (status === 503) return \"The server is busy. Trying again shortly.\";\n  if (/ENOTFOUND|EAI_AGAIN|ECONNREFUSED|ECONNRESET|abort|network|fetch failed/i.test(raw)) {\n    return \"No internet. Jobs will print as soon as the connection is back.\";\n  }\n  if (/printer|spool|lp:|no such (file|printer)/i.test(raw)) {\n    return \"The printer did not accept the job. Check it is switched on, has paper, and is not showing an error.\";\n  }\n  return raw.slice(0, 200);\n}\n\n/** A failure that means \"stop and ask a human\" rather than \"try again\". */\nexport function isFatal(error) {\n  return error?.status === 401 || error?.status === 403;\n}\n\n/**\n * Download a claimed file to a temporary folder.\n *\n * Written to disk because operating system print commands take a path, not a\n * stream — and deleted in a `finally` regardless of how printing went. The\n * shop's promise to its customers is that nothing of theirs stays on this\n * computer, and a file left behind by a failed print would break it quietly.\n */\nexport async function downloadToTemp(url, fileName, fetchImpl = fetch) {\n  const response = await fetchImpl(url);\n  if (!response.ok) throw new Error(`Could not download the file (${response.status})`);\n\n  const buffer = Buffer.from(await response.arrayBuffer());\n  const folder = mkdtempSync(join(tmpdir(), \"dcps-\"));\n  // The server's name for the file is used only for its extension: a file\n  // name arrives from a customer's device and must never decide a path.\n  const extension = /\\.([a-z0-9]{1,5})$/i.exec(String(fileName ?? \"\"))?.[1]?.toLowerCase() ?? \"pdf\";\n  const path = join(folder, `job.${extension.replace(/[^a-z0-9]/g, \"\") || \"pdf\"}`);\n  writeFileSync(path, buffer);\n\n  return {\n    path,\n    cleanup: () => {\n      try {\n        rmSync(folder, { recursive: true, force: true });\n      } catch {\n        /* A file we cannot delete is worth no crash, but it is worth a log. */\n      }\n    },\n  };\n}\n\n/**\n * One job, start to finish.\n *\n * Every exit path reports to the server. A job that is claimed and never\n * reported sits as \"printing\" on the customer's screen until its claim\n * expires — five silent minutes in front of somebody who has already paid.\n */\nexport async function runJob({ api, job, print, log, download = downloadToTemp }) {\n  let claim;\n  try {\n    claim = await api.claim(job.id);\n  } catch (error) {\n    if (error?.status === 409) {\n      log(\"info\", `Job ${job.job_number ?? job.id} was taken by another computer.`);\n      return { outcome: \"skipped\" };\n    }\n    throw error;\n  }\n\n  const file = claim?.file;\n  if (!file?.download_url) {\n    await api.report(job.id, \"failed\", \"The server did not send a file to print.\");\n    return { outcome: \"failed\", message: \"No file on the job.\" };\n  }\n\n  let temp = null;\n  try {\n    temp = await download(file.download_url, file.file_name);\n    log(\"info\", `Printing ${job.job_number ?? job.id}: ${job.copies ?? 1} × ${job.pages ?? \"?\"} pages, ${job.paper_size ?? \"A4\"} ${job.color_mode ?? \"mono\"}.`);\n    await print({ filePath: temp.path, job });\n    await api.report(job.id, \"printed\");\n    log(\"success\", `Printed ${job.job_number ?? job.id}.`);\n    return { outcome: \"printed\" };\n  } catch (error) {\n    const message = describeFailure(error);\n    log(\"error\", `Job ${job.job_number ?? job.id} failed: ${message}`);\n    // Reported as failed so the job returns to the queue and the customer is\n    // told, rather than being left to time out. A failure to report is\n    // swallowed: it must not mask the original problem in the log.\n    await api.report(job.id, \"failed\", message).catch(() => {});\n    return { outcome: \"failed\", message };\n  } finally {\n    temp?.cleanup();\n  }\n}\n\n/**\n * The polling loop.\n *\n * `state` is passed in rather than held here so the setup page can read what\n * the loop is doing — connected or not, what it last printed, what went\n * wrong — without the two sharing anything more than an object.\n */\nexport function createWorker({ api, config, print, log, state, sleep = defaultSleep, printers = [] }) {\n  let running = false;\n  let stopped = false;\n\n  async function tick() {\n    const { jobs, station } = await api.listJobs(printers);\n    state.connected = true;\n    // Shown on the shop's own screen so a partner can see the key landed on\n    // their counter rather than somebody else's.\n    if (station?.display_name) state.stationName = station.display_name;\n    state.lastPollAt = new Date().toISOString();\n    state.queued = Array.isArray(jobs) ? jobs.length : 0;\n\n    const job = nextJob(jobs);\n    if (!job) return false;\n\n    const result = await runJob({ api, job, print, log });\n    if (result.outcome === \"printed\") state.printed += 1;\n    if (result.outcome === \"failed\") state.failed += 1;\n    return true;\n  }\n\n  async function loop() {\n    running = true;\n    let failures = 0;\n\n    while (!stopped) {\n      try {\n        const didWork = await tick();\n        failures = 0;\n        state.lastError = null;\n        // After a print, look again immediately: two customers in a queue\n        // should not wait an interval each.\n        await sleep(didWork ? 250 : config.pollSeconds * 1000);\n      } catch (error) {\n        state.connected = false;\n        state.lastError = describeFailure(error);\n\n        if (isFatal(error)) {\n          log(\"error\", state.lastError);\n          state.stoppedReason = state.lastError;\n          break;\n        }\n        if (!isRetryable(error?.status)) {\n          log(\"error\", state.lastError);\n        }\n\n        failures += 1;\n        const wait = backoffSeconds(failures, config.pollSeconds);\n        if (failures === 1 || failures % 5 === 0) log(\"warn\", `${state.lastError} Retrying in ${wait}s.`);\n        await sleep(wait * 1000);\n      }\n    }\n\n    running = false;\n  }\n\n  return {\n    start: () => {\n      if (running) return;\n      stopped = false;\n      void loop();\n    },\n    stop: () => {\n      stopped = true;\n    },\n    isRunning: () => running,\n    tick,\n  };\n}\n\nfunction defaultSleep(ms) {\n  return new Promise((resolve) => setTimeout(resolve, ms));\n}\n\n/**\n * Answer \"why isn't this working\" once, instead of guessing at it.\n *\n * Returned as a list of plain findings a shop owner can act on, in the order\n * they have to be fixed: an unreachable website makes every later question\n * meaningless, and a dead key makes the printer question moot.\n *\n * The checks deliberately name the values in play — the address being called,\n * the tail of the key being presented — because \"your key was refused\" with\n * no sight of which key or which address is what sent a real shop round the\n * same loop for an afternoon.\n */\nexport async function diagnose({ api, config, printers = [] }) {\n  const findings = [];\n  const add = (level, text) => findings.push({ level, text });\n\n  add(\"info\", `Calling ${config.serverUrl}`);\n  add(\"info\", `Using key ${keyTail(config.agentToken)}`);\n\n  let identity = null;\n  try {\n    identity = await api.whoami();\n  } catch (error) {\n    const status = error?.status;\n\n    if (status === 401) {\n      add(\"error\", \"This key is not the current one for any counter.\");\n      add(\"fix\", \"Open your dashboard, press 'Lost the key? Issue a new one', and paste the key it shows into the box above.\");\n      return findings;\n    }\n    if (status === 503) {\n      add(\"warn\", \"The website cannot reach its database. Nothing is wrong with your key.\");\n      add(\"fix\", \"Leave this running — it will pick up on its own.\");\n      return findings;\n    }\n    if (status === 404) {\n      // The site is up but does not have this endpoint, which means it is\n      // running a version older than this program.\n      add(\"warn\", \"The website answered, but does not know this program yet.\");\n      add(\"fix\", \"The site is still updating. Try again in a few minutes.\");\n      return findings;\n    }\n\n    add(\"error\", describeFailure(error));\n    add(\"fix\", \"Check the website address above, and that this computer is online.\");\n    return findings;\n  }\n\n  add(\"ok\", identity?.message ?? \"Key accepted.\");\n  if (identity?.acceptingOrders === false) {\n    add(\"fix\", \"Switch your counter back on from the dashboard, or customers cannot pay.\");\n  }\n\n  if (!config.printerName) {\n    add(\"error\", \"No printer chosen.\");\n    add(\"fix\", \"Pick your printer from the list above and save.\");\n  } else if (printers.length && !printers.includes(config.printerName)) {\n    // A printer that was unplugged, renamed, or removed. The name saved here\n    // will never match again, and jobs would fail one at a time.\n    add(\"error\", `\"${config.printerName}\" is not on this computer any more.`);\n    add(\"fix\", \"Pick the printer again from the list above and save.\");\n  } else if (config.printerName) {\n    add(\"ok\", `Printing to \"${config.printerName}\".`);\n  }\n\n  return findings;\n}\n\n/** Enough of a key to recognise it, never enough to use it. */\nexport function keyTail(token) {\n  const value = String(token ?? \"\").trim();\n  if (!value) return \"(none)\";\n  return value.length <= 12 ? \"(too short to be a key)\" : `${value.slice(0, 8)}…${value.slice(-4)}`;\n}\n",
  "lib/printer.mjs": "import { execFile } from \"node:child_process\";\nimport { existsSync, renameSync, rmSync, writeFileSync } from \"node:fs\";\nimport { platform } from \"node:os\";\nimport { dirname, join } from \"node:path\";\nimport { fileURLToPath } from \"node:url\";\n\n/**\n * The part that puts ink on paper.\n *\n * Printing a PDF without a human clicking anything is the one genuinely\n * awkward thing this program does, and it is awkward differently on every\n * operating system. The decisions are kept as pure functions here so they can\n * be tested on a machine with no printer attached; only `run` touches the\n * world.\n */\n\nconst IS_WINDOWS = platform() === \"win32\";\nconst IS_MAC = platform() === \"darwin\";\n\n/**\n * Where the printing helper might be, best first.\n *\n * The first entry is the one that matters: the installer drops a copy beside\n * the program, so a shop owner never has to go and find it. The rest are the\n * places a normal install puts it, kept so a computer that already had it\n * does not download a second copy.\n */\nexport function appFolderSumatra() {\n  try {\n    return join(dirname(fileURLToPath(import.meta.url)), \"..\", \"SumatraPDF.exe\");\n  } catch {\n    return \"\";\n  }\n}\n\nexport const SUMATRA_CANDIDATES = [\n  \"C:\\\\Program Files\\\\SumatraPDF\\\\SumatraPDF.exe\",\n  \"C:\\\\Program Files (x86)\\\\SumatraPDF\\\\SumatraPDF.exe\",\n  `${process.env.LOCALAPPDATA ?? \"\"}\\\\SumatraPDF\\\\SumatraPDF.exe`,\n  `${process.env.LOCALAPPDATA ?? \"\"}\\\\Programs\\\\SumatraPDF\\\\SumatraPDF.exe`,\n];\n\nexport function findSumatra(configuredPath, exists = existsSync) {\n  const configured = String(configuredPath ?? \"\").trim();\n  if (configured && exists(configured)) return configured;\n\n  const beside = appFolderSumatra();\n  if (beside && exists(beside)) return beside;\n\n  return SUMATRA_CANDIDATES.find((candidate) => candidate.length > 20 && exists(candidate)) ?? null;\n}\n\n/**\n * The arguments that print a PDF silently through SumatraPDF.\n *\n * `-print-to` names the printer, `-silent` suppresses its window and every\n * error dialog, and `-exit-when-done` stops a shop ending the day with two\n * hundred open viewers. The print settings string carries copies, paper size\n * and colour, because SumatraPDF has no separate flags for them.\n */\nexport function sumatraArgs({ filePath, printerName, job, duplex = false }) {\n  const settings = [`${Math.max(1, job.copies ?? 1)}x`, \"fit\"];\n  if (String(job.paper_size ?? \"A4\").toUpperCase() === \"A3\") settings.push(\"paper=A3\");\n  else settings.push(\"paper=A4\");\n  settings.push(job.color_mode === \"color\" ? \"color\" : \"monochrome\");\n  if (duplex) settings.push(\"duplex\");\n\n  return [\"-print-to\", printerName, \"-print-settings\", settings.join(\",\"), \"-silent\", \"-exit-when-done\", filePath];\n}\n\n/**\n * The CUPS command, used on macOS and Linux.\n *\n * `lp` takes each setting as its own option, which is why this does not share\n * a shape with the Windows path — pretending they were the same would mean\n * one of them silently ignoring copies.\n */\nexport function lpArgs({ filePath, printerName, job, duplex = false }) {\n  const args = [\"-d\", printerName, \"-n\", String(Math.max(1, job.copies ?? 1))];\n  args.push(\"-o\", `media=${String(job.paper_size ?? \"A4\").toUpperCase() === \"A3\" ? \"A3\" : \"A4\"}`);\n  args.push(\"-o\", job.color_mode === \"color\" ? \"ColorModel=RGB\" : \"ColorModel=Gray\");\n  if (duplex) args.push(\"-o\", \"sides=two-sided-long-edge\");\n  args.push(filePath);\n  return args;\n}\n\n/**\n * Pick how to print, given what is installed.\n *\n * Returned as data rather than executed, so the choice is testable and so the\n * setup page can tell a shop owner which route their machine will take before\n * a customer is standing there waiting.\n */\nexport function choosePrintCommand({ filePath, printerName, job, config, os = platform(), exists = existsSync }) {\n  if (os === \"win32\") {\n    /*\n      Photos first, because Windows can print them itself.\n\n      This is not a fallback — it is better than handing an image to a\n      viewer, which is how a real job died: no application on that computer\n      was associated with .webp, and there was nothing to hand it to.\n    */\n    if (isImageFile(filePath)) {\n      return {\n        kind: \"dotnet-image\",\n        command: \"powershell.exe\",\n        args: [\"-NoProfile\", \"-NonInteractive\", \"-Command\", imagePrintScript({ filePath, printerName, job })],\n      };\n    }\n\n    const sumatra = findSumatra(config?.sumatraPath, exists);\n    if (sumatra) {\n      return { kind: \"sumatra\", command: sumatra, args: sumatraArgs({ filePath, printerName, job, duplex: config?.duplex }) };\n    }\n    /*\n      The fallback when SumatraPDF is not there.\n\n      Windows' PrintTo verb honours the printer and nothing else — it cannot\n      be told the paper size or whether to use colour. So those are set on the\n      printer itself first, with Windows' own Set-PrintConfiguration, and put\n      back afterwards. Copies are still sent as separate calls by the caller,\n      because no amount of printer configuration adds a copy count to a shell\n      verb.\n\n      This route is second choice, not a broken one: a customer who paid for\n      an A3 colour page gets an A3 colour page. What it cannot promise is\n      speed, since it opens the system's PDF viewer once per copy.\n    */\n    return {\n      kind: \"shell-verb\",\n      command: \"powershell.exe\",\n      args: [\"-NoProfile\", \"-NonInteractive\", \"-Command\", shellVerbScript({ filePath, printerName, job })],\n      /*\n        Honest about what this can and cannot do.\n\n        It works only if some application on that computer has registered\n        itself to print this file type. For PDFs that usually means Adobe\n        Reader; Edge does not. When nothing has, the job fails with a message\n        about no associated application — which is what happened at a real\n        counter while the log claimed this route \"works fine\".\n      */\n      degraded:\n        \"No fast printing helper found, so this goes through whichever app opens PDFs on this computer. If nothing does, PDFs will fail — photos are unaffected.\",\n    };\n  }\n\n  return { kind: IS_MAC ? \"lp\" : \"lp\", command: \"lp\", args: lpArgs({ filePath, printerName, job, duplex: config?.duplex }) };\n}\n\n/** Photos, which Windows can print itself — see below. */\nconst IMAGE_EXTENSIONS = [\"jpg\", \"jpeg\", \"png\", \"webp\", \"bmp\", \"gif\", \"tif\", \"tiff\"];\n\nexport function isImageFile(filePath) {\n  const extension = /\\.([a-z0-9]+)$/i.exec(String(filePath ?? \"\"))?.[1]?.toLowerCase();\n  return Boolean(extension && IMAGE_EXTENSIONS.includes(extension));\n}\n\n/**\n * Print a photo using Windows' own drawing library.\n *\n * The lesson from a real counter: a customer paid for a .webp and the job\n * died on \"No application is associated with the specified file for this\n * operation.\" Windows has no PrintTo handler for webp — and often none for\n * PDF either — so handing the file to the shell was never the safe fallback\n * I claimed it was.\n *\n * .NET can print an image directly, with no helper application involved at\n * all. It also takes the copies, the paper size and the colour setting\n * properly, which the shell verb never could. Photos and screenshots are most\n * of what a counter prints, so this is the path that matters most.\n */\nexport function imagePrintScript({ filePath, printerName, job }) {\n  const copies = Math.max(1, Math.min(99, Math.round(Number(job?.copies) || 1)));\n  const paper = String(job?.paper_size ?? \"A4\").toUpperCase() === \"A3\" ? \"A3\" : \"A4\";\n  const colour = job?.color_mode === \"color\" ? \"$true\" : \"$false\";\n\n  return [\n    \"$ErrorActionPreference = 'Stop'\",\n    \"try {\",\n    \"  Add-Type -AssemblyName System.Drawing\",\n    `  $script:img = [System.Drawing.Image]::FromFile(${quoteForPowerShell(filePath)})`,\n    \"  $doc = New-Object System.Drawing.Printing.PrintDocument\",\n    `  $doc.PrinterSettings.PrinterName = ${quoteForPowerShell(printerName)}`,\n    // A printer name that no longer matches anything must say so, rather than\n    // silently printing to whatever Windows considers the default.\n    `  if (-not $doc.PrinterSettings.IsValid) { throw 'Printer not found: ' + ${quoteForPowerShell(printerName)} }`,\n    `  $doc.PrinterSettings.Copies = ${copies}`,\n    `  $doc.DefaultPageSettings.Color = ${colour}`,\n    `  $paper = $doc.PrinterSettings.PaperSizes | Where-Object { $_.PaperName -eq '${paper}' } | Select-Object -First 1`,\n    \"  if ($paper) { $doc.DefaultPageSettings.PaperSize = $paper }\",\n    \"  $doc.DocumentName = 'DigiConnect print'\",\n    \"  $doc.add_PrintPage({\",\n    \"    param($sender, $e)\",\n    // Fit inside the printable area without distorting it: a customer's\n    // photo stretched to the page edges is a wasted sheet they paid for.\n    \"    $area = $e.MarginBounds\",\n    \"    $scale = [Math]::Min($area.Width / $script:img.Width, $area.Height / $script:img.Height)\",\n    \"    $w = [int]($script:img.Width * $scale)\",\n    \"    $h = [int]($script:img.Height * $scale)\",\n    \"    $x = $area.X + [int](($area.Width - $w) / 2)\",\n    \"    $y = $area.Y + [int](($area.Height - $h) / 2)\",\n    \"    $e.Graphics.DrawImage($script:img, $x, $y, $w, $h)\",\n    \"    $e.HasMorePages = $false\",\n    \"  })\",\n    \"  $doc.Print()\",\n    \"  $doc.Dispose()\",\n    \"  $script:img.Dispose()\",\n    \"} catch {\",\n    // Without an explicit non-zero exit, powershell.exe reports success and\n    // the shop is told the page printed when it did not.\n    \"  Write-Error $_.Exception.Message\",\n    \"  exit 1\",\n    \"}\",\n  ].join(\"\\n\");\n}\n\n/**\n * The PowerShell that prints one copy through Windows' own viewer.\n *\n * Built as a string here rather than run, so the exact commands a shop's\n * computer will execute can be checked in a test on a machine with no\n * printer. Every step that touches printer settings is wrapped: a printer\n * that refuses to be reconfigured should still print the page, on whatever\n * its defaults are, rather than fail the job outright.\n */\nexport function shellVerbScript({ filePath, printerName, job }) {\n  const printer = quoteForPowerShell(printerName);\n  const paper = String(job?.paper_size ?? \"A4\").toUpperCase() === \"A3\" ? \"A3\" : \"A4\";\n  const colour = job?.color_mode === \"color\" ? \"$true\" : \"$false\";\n\n  return [\n    \"$ErrorActionPreference = 'Stop'\",\n    `try { Set-PrintConfiguration -PrinterName ${printer} -PaperSize ${paper} -Color ${colour} } catch { }`,\n    `$p = Start-Process -FilePath ${quoteForPowerShell(filePath)} -Verb PrintTo -ArgumentList ${printer} -PassThru`,\n    \"if ($p) { Wait-Process -Id $p.Id -Timeout 120 -ErrorAction SilentlyContinue }\",\n    // The viewer can linger after the spool; closing it keeps a shop from\n    // ending the day behind two hundred open windows.\n    \"if ($p -and -not $p.HasExited) { Stop-Process -Id $p.Id -Force -ErrorAction SilentlyContinue }\",\n  ].join(\"; \");\n}\n\n/** Single-quote a value for PowerShell, doubling any quote inside it. */\nexport function quoteForPowerShell(value) {\n  return `'${String(value).replace(/'/g, \"''\")}'`;\n}\n\n/**\n * Is this actually a Windows program, or a 404 page wearing its name?\n *\n * A missed download that saved the site's HTML error page as SumatraPDF.exe\n * would be found by every later lookup and fail every print, with a message\n * about the printer rather than about the file. Every executable begins \"MZ\";\n * nothing else here does.\n */\nexport function looksLikeWindowsProgram(head) {\n  return Buffer.isBuffer(head) && head.length > 2 && head[0] === 0x4d && head[1] === 0x5a;\n}\n\n/**\n * Fetch the printing helper once, so no shop owner ever installs anything.\n *\n * Best effort by design: the program prints perfectly well without it through\n * Windows' own viewer, so every failure here logs a line and returns. The\n * file is written under a temporary name and only moved into place once it\n * has been checked, because a half-written or wrong file is worse than none.\n */\nexport async function ensurePrintHelper({ serverUrl, config, log, fetchImpl = fetch }) {\n  if (platform() !== \"win32\") return null;\n\n  const existing = findSumatra(config?.sumatraPath);\n  if (existing) return existing;\n\n  const target = appFolderSumatra();\n  if (!target) return null;\n  const temporary = `${target}.part`;\n\n  try {\n    const response = await fetchImpl(`${String(serverUrl).replace(/\\/+$/, \"\")}/print-station/SumatraPDF.exe`);\n    if (!response.ok) throw new Error(String(response.status));\n\n    const bytes = Buffer.from(await response.arrayBuffer());\n    if (!looksLikeWindowsProgram(bytes)) throw new Error(\"not a program\");\n\n    writeFileSync(temporary, bytes);\n    renameSync(temporary, target);\n    log?.(\"info\", \"Fast printing helper installed.\");\n    return target;\n  } catch {\n    try {\n      rmSync(temporary, { force: true });\n    } catch {\n      /* Nothing to clean up. */\n    }\n    /*\n      Said precisely, because the old wording — \"works fine\" — was read by a\n      shop owner as reassurance right before a job failed for exactly the\n      reason this line should have warned about.\n    */\n    log?.(\n      \"info\",\n      \"No fast printing helper. Photos print normally; PDFs need an app on this computer that can print them.\",\n    );\n    return null;\n  }\n}\n\n/* ─────────────────────────────────────────────────────────────────────────\n   Talking to the machine\n   ───────────────────────────────────────────────────────────────────────── */\n\nfunction run(command, args, timeout = 120_000) {\n  return new Promise((resolve, reject) => {\n    execFile(command, args, { timeout, windowsHide: true }, (error, stdout, stderr) => {\n      if (error) {\n        reject(new Error(String(stderr || error.message).trim().slice(0, 400)));\n        return;\n      }\n      resolve(String(stdout));\n    });\n  });\n}\n\n/** Parse `wmic`/PowerShell printer output into names. */\nexport function parseWindowsPrinters(stdout) {\n  return String(stdout)\n    .split(/\\r?\\n/)\n    .map((line) => line.trim())\n    .filter((line) => line && line.toLowerCase() !== \"name\" && !/^-+$/.test(line));\n}\n\n/** Parse `lpstat -a` into names. CUPS puts the queue first, then prose. */\nexport function parseCupsPrinters(stdout) {\n  return String(stdout)\n    .split(/\\r?\\n/)\n    .map((line) => line.trim().split(/\\s+/)[0])\n    .filter(Boolean);\n}\n\n/** Every printer this computer can see, by the name the OS uses. */\nexport async function listPrinters() {\n  try {\n    if (IS_WINDOWS) {\n      const stdout = await run(\n        \"powershell.exe\",\n        [\"-NoProfile\", \"-NonInteractive\", \"-Command\", \"Get-Printer | Select-Object -ExpandProperty Name\"],\n        20_000,\n      );\n      return parseWindowsPrinters(stdout);\n    }\n    return parseCupsPrinters(await run(\"lpstat\", [\"-a\"], 20_000));\n  } catch {\n    // No printers is a state the setup page can show. An exception here would\n    // take the whole setup page down with it.\n    return [];\n  }\n}\n\n/**\n * Print one job's file.\n *\n * Resolves when the print command returns, which is when the file has been\n * handed to the spooler — not when the last page lands in the tray. No\n * consumer operating system reliably tells a program the latter, and claiming\n * otherwise in the customer's status would be a lie.\n */\nexport async function printFile({ filePath, printerName, job, config }) {\n  const plan = choosePrintCommand({ filePath, printerName, job, config });\n\n  /*\n    The .NET path prints every copy itself through PrinterSettings.Copies, so\n    it runs once. Looping it would charge a customer for three and give them\n    nine.\n  */\n  if (plan.kind === \"dotnet-image\") {\n    await run(plan.command, plan.args);\n    return plan;\n  }\n\n  if (plan.kind === \"shell-verb\") {\n    // This route cannot ask for copies, so it asks the same number of times.\n    const copies = Math.max(1, Math.min(20, job.copies ?? 1));\n    for (let index = 0; index < copies; index += 1) {\n      await run(plan.command, plan.args);\n    }\n    return plan;\n  }\n\n  await run(plan.command, plan.args);\n  return plan;\n}\n",
  "lib/page.mjs": "/**\n * The setup screen, served on this computer only.\n *\n * One HTML file with no build step and no dependencies, because the thing\n * standing between a shop and a working printer should not be a toolchain.\n * It looks like the DigiConnect dashboard on purpose: a partner who has just\n * copied their key from the website should recognise where they have landed.\n */\n\nexport function renderPage() {\n  return `<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n<title>DigiConnect Print Station</title>\n<style>\n  :root {\n    --ink: #0b1220; --body: #55617a; --line: rgba(15,32,73,.12);\n    --blue: linear-gradient(135deg,#1f4fd8,#3b82f6); --flame: #f4632e;\n    --ok: #0f9d58; --bg: #eef2fb;\n  }\n  * { box-sizing: border-box; }\n  /* Every pill here is display:inline-flex, which outranks the hidden\n     attribute's own rule and would leave an empty bubble on the screen. */\n  [hidden] { display: none !important; }\n  body { margin:0; background:\n      radial-gradient(1000px 600px at 15% -10%, #dfe8ff 0%, transparent 60%),\n      radial-gradient(800px 500px at 95% 0%, #ffe6dc 0%, transparent 55%), var(--bg);\n    font: 14px/1.55 system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif; color: var(--ink);\n    min-height: 100vh; padding: 28px 16px 64px; }\n  .wrap { max-width: 720px; margin: 0 auto; }\n  .card { background: rgba(255,255,255,.72); backdrop-filter: blur(18px);\n    border: 1px solid var(--line); border-radius: 20px; padding: 20px;\n    box-shadow: 0 18px 50px -30px rgba(15,32,73,.5); margin-bottom: 16px; }\n  h1 { font-size: 21px; margin: 0; letter-spacing: -.4px; }\n  h2 { font-size: 14px; margin: 0 0 12px; }\n  p { color: var(--body); margin: 6px 0 0; }\n  .head { display:flex; align-items:center; gap:12px; }\n  .mark { width:44px; height:44px; border-radius:14px; background: var(--blue); color:#fff;\n    display:grid; place-items:center; font-size:20px; flex:none; }\n  label { display:block; margin-top:14px; font-size:12px; font-weight:700; }\n  input, select { width:100%; margin-top:6px; padding:11px 12px; border-radius:12px;\n    border:1px solid var(--line); background:rgba(255,255,255,.9); font:inherit; color:var(--ink); }\n  input:focus, select:focus { outline:2px solid #3b82f6; outline-offset:1px; }\n  .row { display:flex; gap:10px; flex-wrap:wrap; margin-top:16px; }\n  button { border:0; border-radius:12px; padding:11px 18px; font:inherit; font-weight:700; cursor:pointer; }\n  .primary { background: var(--blue); color:#fff; }\n  .ghost { background: rgba(255,255,255,.9); border:1px solid var(--line); color:var(--body); }\n  button:disabled { opacity:.55; cursor:default; }\n  .pill { display:inline-flex; align-items:center; gap:7px; font-weight:800; font-size:12.5px;\n    padding:6px 12px; border-radius:999px; background:rgba(255,255,255,.9); border:1px solid var(--line); }\n  .dot { width:8px; height:8px; border-radius:50%; background:#c3cbdc; }\n  .on .dot { background: var(--ok); box-shadow:0 0 0 4px rgba(15,157,88,.15); }\n  .off .dot { background: var(--flame); box-shadow:0 0 0 4px rgba(244,99,46,.15); }\n  .stats { display:grid; grid-template-columns:repeat(3,1fr); gap:10px; margin-top:14px; }\n  .stat { background:rgba(255,255,255,.9); border:1px solid var(--line); border-radius:14px; padding:12px; }\n  .stat b { display:block; font-size:21px; letter-spacing:-.5px; }\n  .stat span { font-size:11.5px; color:var(--body); font-weight:600; }\n  .log { margin-top:14px; max-height:260px; overflow:auto; font:12px/1.6 ui-monospace, Menlo, Consolas, monospace; }\n  .log div { padding:4px 0; border-bottom:1px dashed var(--line); color:var(--body); }\n  .log .error { color:var(--flame); font-weight:700; }\n  .log .success { color:var(--ok); }\n  .log .warn { color:#b26a00; }\n  .warn-box { margin-top:12px; border-left:3px solid var(--flame); padding:10px 12px;\n    background:rgba(244,99,46,.07); border-radius:0 12px 12px 0; font-size:12.5px; }\n  /* Deliberately not \".mark\": that class is already the 44px header tile\n     above, and reusing it made every finding sprout a blue square. */\n  .findings { margin-top:14px; display:grid; gap:6px; }\n  .finding { display:grid; grid-template-columns:5.2rem 1fr; gap:10px; align-items:baseline;\n    padding:9px 12px; border-radius:10px; border:1px solid var(--line);\n    background:rgba(255,255,255,.92); font-size:12.5px; line-height:1.5; color:var(--body); }\n  .finding .tag { font-weight:800; font-size:10.5px; letter-spacing:.09em; text-transform:uppercase; }\n  .finding.ok    { border-left:3px solid var(--ok); }\n  .finding.ok    .tag { color:var(--ok); }\n  .finding.error { border-left:3px solid var(--flame); background:rgba(244,99,46,.06); }\n  .finding.error .tag, .finding.error span:last-child { color:var(--flame); font-weight:600; }\n  .finding.warn  { border-left:3px solid #b26a00; }\n  .finding.warn  .tag { color:#b26a00; }\n  .finding.info  { opacity:.85; }\n  .finding.info  .tag { color:var(--faint, #9aa4b8); }\n  .finding.fix   { border-left:3px solid #1f4fd8; background:rgba(31,79,216,.06); }\n  .finding.fix   .tag { color:#1f4fd8; }\n  .finding.fix   span:last-child { color:var(--ink); font-weight:600; }\n  .muted { font-size:12px; color:var(--body); }\n  a { color:#1f4fd8; }\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <div class=\"card\">\n    <div class=\"head\">\n      <span class=\"mark\">&#128424;</span>\n      <div>\n        <h1>DigiConnect Print Station</h1>\n        <p class=\"muted\">This computer prints what your customers order. <span id=\"version\"></span></p>\n      </div>\n    </div>\n    <div class=\"row\" id=\"status-row\">\n      <span class=\"pill\" id=\"conn\"><span class=\"dot\"></span><span id=\"conn-text\">Starting…</span></span>\n      <span class=\"pill\" id=\"station-pill\" hidden></span>\n    </div>\n    <div class=\"stats\">\n      <div class=\"stat\"><b id=\"s-queued\">0</b><span>Waiting</span></div>\n      <div class=\"stat\"><b id=\"s-printed\">0</b><span>Printed</span></div>\n      <div class=\"stat\"><b id=\"s-failed\">0</b><span>Failed</span></div>\n    </div>\n    <div class=\"warn-box\" id=\"problem\" hidden></div>\n    <div class=\"findings\" id=\"findings\" hidden></div>\n  </div>\n\n  <div class=\"card\">\n    <h2>Settings</h2>\n    <form id=\"form\">\n      <label>Your key\n        <input name=\"agentToken\" id=\"agentToken\" placeholder=\"dcp_…\" autocomplete=\"off\" spellcheck=\"false\" />\n      </label>\n      <p class=\"muted\">Copy it from your partner dashboard &rarr; Print counter. It is shown only once.</p>\n\n      <label>Printer\n        <select name=\"printerName\" id=\"printerName\"></select>\n      </label>\n\n      <label>Website address\n        <input name=\"serverUrl\" id=\"serverUrl\" />\n      </label>\n\n      <label>Check for new jobs every\n        <input name=\"pollSeconds\" id=\"pollSeconds\" type=\"number\" min=\"2\" max=\"60\" />\n      </label>\n\n      <label style=\"margin-top:14px; font-weight:600; display:flex; gap:9px; align-items:center;\">\n        <input type=\"checkbox\" name=\"duplex\" id=\"duplex\" style=\"width:auto; margin:0;\" />\n        Print on both sides when the printer supports it\n      </label>\n\n      <div class=\"row\">\n        <button class=\"primary\" type=\"submit\" id=\"save\">Save and start</button>\n        <button class=\"ghost\" type=\"button\" id=\"check\">Kya galat hai? Check kijiye</button>\n        <button class=\"ghost\" type=\"button\" id=\"test\">Print a test page</button>\n      </div>\n    </form>\n  </div>\n\n  <div class=\"card\">\n    <h2>What has happened</h2>\n    <div class=\"log\" id=\"log\"></div>\n  </div>\n</div>\n\n<script>\n  const $ = (id) => document.getElementById(id);\n  let loadedOnce = false;\n\n  function paint(state) {\n    const conn = $(\"conn\");\n    conn.className = \"pill \" + (state.running && state.connected ? \"on\" : \"off\");\n    $(\"conn-text\").textContent = state.stoppedReason\n      ? \"Stopped\"\n      : state.running\n        ? (state.connected ? \"Connected\" : \"Trying to reach the website…\")\n        : \"Not started\";\n\n    if (state.stationName) {\n      $(\"station-pill\").hidden = false;\n      $(\"station-pill\").textContent = state.stationName;\n    }\n\n    if (state.version) $(\"version\").textContent = \"\\u00b7 v\" + state.version;\n    $(\"s-queued\").textContent = state.queued ?? 0;\n    $(\"s-printed\").textContent = state.printed ?? 0;\n    $(\"s-failed\").textContent = state.failed ?? 0;\n\n    const problem = state.stoppedReason || state.lastError || (state.problems || [])[0] || \"\";\n    $(\"problem\").hidden = !problem;\n    $(\"problem\").textContent = problem;\n\n    if (!loadedOnce) {\n      $(\"agentToken\").value = state.config.agentToken || \"\";\n      $(\"serverUrl\").value = state.config.serverUrl || \"\";\n      $(\"pollSeconds\").value = state.config.pollSeconds || 5;\n      $(\"duplex\").checked = !!state.config.duplex;\n\n      const select = $(\"printerName\");\n      select.innerHTML = \"\";\n      const names = state.printers && state.printers.length ? state.printers : [];\n      if (!names.length) {\n        select.appendChild(new Option(\"No printer found on this computer\", \"\"));\n      }\n      for (const name of names) {\n        const option = new Option(name, name);\n        if (name === state.config.printerName) option.selected = true;\n        select.appendChild(option);\n      }\n      loadedOnce = true;\n    }\n\n    $(\"log\").innerHTML = (state.log || [])\n      .map((line) => '<div class=\"' + line.level + '\">' +\n        new Date(line.at).toLocaleTimeString() + \" &nbsp; \" +\n        line.message.replace(/[<>&]/g, (c) => ({ \"<\": \"&lt;\", \">\": \"&gt;\", \"&\": \"&amp;\" }[c])) + \"</div>\")\n      .join(\"\");\n  }\n\n  async function refresh() {\n    try { paint(await (await fetch(\"/api/state\")).json()); } catch {}\n  }\n\n  $(\"form\").addEventListener(\"submit\", async (event) => {\n    event.preventDefault();\n    $(\"save\").disabled = true;\n    const body = {\n      agentToken: $(\"agentToken\").value,\n      printerName: $(\"printerName\").value,\n      serverUrl: $(\"serverUrl\").value,\n      pollSeconds: Number($(\"pollSeconds\").value),\n      duplex: $(\"duplex\").checked,\n    };\n    try {\n      const response = await fetch(\"/api/save\", {\n        method: \"POST\", headers: { \"Content-Type\": \"application/json\" }, body: JSON.stringify(body),\n      });\n      const json = await response.json();\n      if (json.problems && json.problems.length) alert(json.problems.join(\"\\\\n\"));\n    } finally {\n      $(\"save\").disabled = false;\n      refresh();\n    }\n  });\n\n  $(\"check\").addEventListener(\"click\", async () => {\n    $(\"check\").disabled = true;\n    $(\"check\").textContent = \"Check kar rahe hain…\";\n    try {\n      const json = await (await fetch(\"/api/check\", { method: \"POST\" })).json();\n      const box = $(\"findings\");\n      box.hidden = false;\n      const label = { ok: \"Theek\", error: \"Gadbad\", warn: \"Dhyan\", fix: \"Ye kariye\", info: \"\" };\n      box.innerHTML = (json.findings || [])\n        .map((f) => '<div class=\"finding ' + f.level + '\"><span class=\"tag\">' +\n          (label[f.level] || \"\") + '</span><span>' +\n          f.text.replace(/[<>&]/g, (c) => ({ \"<\": \"&lt;\", \">\": \"&gt;\", \"&\": \"&amp;\" }[c])) + \"</span></div>\")\n        .join(\"\");\n    } catch {\n      alert(\"Check nahi ho paya. Kya ye program abhi bhi chal raha hai?\");\n    } finally {\n      $(\"check\").disabled = false;\n      $(\"check\").textContent = \"Kya galat hai? Check kijiye\";\n      refresh();\n    }\n  });\n\n  $(\"test\").addEventListener(\"click\", async () => {\n    $(\"test\").disabled = true;\n    try {\n      const json = await (await fetch(\"/api/test-print\", { method: \"POST\" })).json();\n      alert(json.ok ? \"Sent to \" + json.printer + \". Check the tray.\" : (json.error || \"Could not print.\"));\n    } finally {\n      $(\"test\").disabled = false;\n      refresh();\n    }\n  });\n\n  refresh();\n  setInterval(refresh, 2000);\n</script>\n</body>\n</html>`;\n}\n",
  "lib/log.mjs": "/**\n * What the shop owner sees when something goes wrong.\n *\n * Kept in memory and capped: this program runs for months on a counter PC\n * that nobody restarts, and an unbounded log is a memory leak with a\n * respectable name. Nothing here is written to disk — a customer's file name\n * passes through these lines, and the promise is that nothing of theirs stays\n * on this computer.\n */\n\nconst MAX_LINES = 200;\n\nexport function createLog() {\n  const lines = [];\n\n  function push(level, message) {\n    lines.unshift({ at: new Date().toISOString(), level, message: String(message).slice(0, 500) });\n    if (lines.length > MAX_LINES) lines.length = MAX_LINES;\n\n    const stamp = new Date().toLocaleTimeString();\n    const prefix = { error: \"!\", warn: \"*\", success: \"+\", info: \" \" }[level] ?? \" \";\n    console.log(`${stamp} ${prefix} ${message}`);\n  }\n\n  return { push, lines: () => lines.slice(0, 60) };\n}\n",
  "lib/version.mjs": "/**\n * Which build of the Print Station this is.\n *\n * Printed on startup and shown on the settings page for one reason: a shop\n * owner sent screenshot after screenshot of a failure that had already been\n * fixed, because nothing on screen said which version was running and the\n * Downloads folder held four copies with identical names. The version answers\n * that in the first line of the log.\n *\n * Bump it whenever the program's behaviour changes.\n */\nexport const PRINT_STATION_VERSION = \"1.4.0\";\n",
  "lib/background.ps1": "<#\n  Printing that survives the window being closed.\n\n  The counter PC's black window was doing two jobs: running the program, and\n  reminding the shop it was running. It did the second badly and the first\n  fatally -- one accidental X, or one \"clean up the desktop\" at closing time,\n  and the next customer paid for pages that never came out. Nobody at a busy\n  shop should have to guard a console window.\n\n  So the program is started with no window, and again every time the computer\n  is switched on. Nothing here needs administrator rights: it writes one\n  shortcut into the user's own Startup folder, which is why it works on a\n  shared shop machine whose owner is not an admin.\n\n      powershell -ExecutionPolicy Bypass -File lib\\background.ps1\n      powershell -ExecutionPolicy Bypass -File lib\\background.ps1 -Remove\n#>\nparam([switch]$Remove)\n\n$ErrorActionPreference = \"Stop\"\n\n$folder  = Split-Path -Parent $PSScriptRoot\n$startup = [Environment]::GetFolderPath(\"Startup\")\n$link    = Join-Path $startup \"DigiConnect Print Station.lnk\"\n$vbs     = Join-Path $folder \"lib\\run-hidden.vbs\"\n$ps1     = Join-Path $folder \"lib\\run-hidden.ps1\"\n$wscript = Join-Path $env:WINDIR \"System32\\wscript.exe\"\n$port    = if ($env:DCPS_PORT) { $env:DCPS_PORT } else { \"7171\" }\n\n<#\n  Stop whichever copy is already running.\n\n  Matched on the command line rather than on \"node.exe\" alone, because a\n  counter PC may be running somebody else's Node program and killing that\n  would be a worse bug than the one being fixed here.\n#>\nfunction Stop-Station {\n  Get-CimInstance Win32_Process -Filter \"Name = 'node.exe'\" -ErrorAction SilentlyContinue |\n    Where-Object { $_.CommandLine -and $_.CommandLine -like \"*station.mjs*\" } |\n    ForEach-Object { Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue }\n}\n\nfunction Test-Station {\n  foreach ($attempt in 1..12) {\n    Start-Sleep -Seconds 1\n    try {\n      return Invoke-RestMethod -Uri \"http://localhost:$port/api/state\" -TimeoutSec 2\n    } catch {\n      # Not up yet. Node takes a moment, and listing printers takes longer.\n    }\n  }\n  return $null\n}\n\nif (-not (Test-Path (Join-Path $folder \"station.mjs\"))) {\n  Write-Host \"\"\n  Write-Host \"  station.mjs nahi mili. Poori zip Extract kijiye aur folder ke\" -ForegroundColor Yellow\n  Write-Host \"  ANDAR se ye file chalaiye.\" -ForegroundColor Yellow\n  Write-Host \"\"\n  exit 1\n}\n\nif ($Remove) {\n  if (Test-Path $link) { Remove-Item $link -Force }\n  Stop-Station\n  Write-Host \"\"\n  Write-Host \"  Background printing band kar di.\" -ForegroundColor Yellow\n  Write-Host \"  Ab print tabhi hoga jab aap khud 'Start Print Station' chalayenge.\"\n  Write-Host \"\"\n  exit 0\n}\n\nif (-not (Get-Command node -ErrorAction SilentlyContinue)) {\n  Write-Host \"\"\n  Write-Host \"  Pehle Node.js install kijiye: https://nodejs.org/en/download\" -ForegroundColor Yellow\n  Write-Host \"  ('LTS' wala button.) Uske baad ye file dobara chalaiye.\"\n  Write-Host \"\"\n  exit 1\n}\n\n$useVbs = Test-Path $wscript\n\n$shell = New-Object -ComObject WScript.Shell\n$shortcut = $shell.CreateShortcut($link)\nif ($useVbs) {\n  $shortcut.TargetPath = $wscript\n  $shortcut.Arguments  = \"`\"$vbs`\"\"\n} else {\n  $shortcut.TargetPath = \"powershell.exe\"\n  $shortcut.Arguments  = \"-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File `\"$ps1`\"\"\n}\n$shortcut.WorkingDirectory = $folder\n$shortcut.Description = \"Prints what your customers order at your QR counter\"\n$shortcut.Save()\n\n# Start it now, so the shop does not have to restart the computer to see this\n# work. Any copy started from the black window is stopped first, or the new\n# one would find the port taken and quit straight away.\nStop-Station\nStart-Sleep -Seconds 1\nif ($useVbs) {\n  Start-Process -FilePath $wscript -ArgumentList \"`\"$vbs`\"\" -WindowStyle Hidden\n} else {\n  Start-Process -FilePath \"powershell.exe\" -ArgumentList \"-NoProfile\",\"-ExecutionPolicy\",\"Bypass\",\"-WindowStyle\",\"Hidden\",\"-File\",\"`\"$ps1`\"\" -WindowStyle Hidden\n}\n\n$state = Test-Station\n\nWrite-Host \"\"\nif ($state) {\n  Write-Host \"  Ho gaya. Print Station ab background me chal raha hai.\" -ForegroundColor Green\n  Write-Host \"\"\n  Write-Host \"  * Koi window khuli rakhne ki zaroorat nahi.\"\n  Write-Host \"  * Computer on hote hi khud chalu ho jayega.\"\n  if ($state.config -and $state.config.printerName) {\n    Write-Host \"  * Printer: $($state.config.printerName)\"\n  }\n  Write-Host \"  * Haal dekhna ho to: http://localhost:$port\"\n  Write-Host \"  * Band karna ho to 'Background band kijiye' par double-click.\"\n  Write-Host \"\"\n  # The startup shortcut points at this folder. A newer download lands in a\n  # new folder with a new key, and the old hidden copy would keep starting\n  # with the retired one -- silently, now that there is no window to see it.\n  Write-Host \"  Jab bhi naya version download karen, us naye folder se ye file\"\n  Write-Host \"  dobara chalaiye - warna purana folder hi chalta rahega.\"\n} else {\n  Write-Host \"  Startup me daal diya, lekin chalu hua ya nahi ye pakka nahi.\" -ForegroundColor Yellow\n  Write-Host \"\"\n  Write-Host \"  http://localhost:$port kholkar dekhiye. Page na khule to ek baar\"\n  Write-Host \"  'Start Print Station' se chalaiye - wahan galti likhi hui milegi.\"\n}\nWrite-Host \"\"\n",
  "lib/run-hidden.vbs": "' Starts the Print Station with no window at all.\n'\n' The shop asked the obvious question: why must a black window stay open on\n' the counter PC all day? It must not. This is the same program, started\n' with the window hidden, so closing nothing stops printing.\n'\n' It works out its own folder rather than being told one, so the shop can\n' move or rename the folder and this keeps working.\nOption Explicit\n\nDim fso, shell, folder\nSet fso = CreateObject(\"Scripting.FileSystemObject\")\nSet shell = CreateObject(\"WScript.Shell\")\n\nfolder = fso.GetParentFolderName(fso.GetParentFolderName(WScript.ScriptFullName))\n\nIf Not fso.FileExists(folder & \"\\station.mjs\") Then\n  WScript.Quit 1\nEnd If\n\nshell.CurrentDirectory = folder\n' 0 = no window, False = do not wait for it to finish.\nshell.Run \"node \"\"\" & folder & \"\\station.mjs\"\"\", 0, False\n",
  "lib/run-hidden.ps1": "<#\n  The same hidden start, for a Windows without VBScript.\n\n  VBScript is on its way out of Windows, and a shop that has already removed\n  it would otherwise get a startup entry that silently does nothing. This is\n  the fallback the shortcut points at in that case.\n#>\n$ErrorActionPreference = \"Stop\"\n\n$folder = Split-Path -Parent $PSScriptRoot\n$station = Join-Path $folder \"station.mjs\"\nif (-not (Test-Path $station)) { exit 1 }\n\nStart-Process -FilePath \"node\" -ArgumentList \"`\"$station`\"\" -WorkingDirectory $folder -WindowStyle Hidden\n",
};
